    // exprList evaluates a list of expressions and returns the corresponding operands.
    // A single-element expression list may evaluate to multiple operands.
    gocpp::slice<operand*> rec::exprList(Checker* check, gocpp::slice<ast::Expr> elist)
    {
        gocpp::slice<operand*> xlist;
        if(auto n = len(elist); n == 1)
        {
            std::tie(xlist, std::ignore) = rec::multiExpr(gocpp::recv(check), elist[0], false);
        }
        else
        if(n > 1)
        {
            // multiple (possibly invalid) values
            xlist = gocpp::make(gocpp::Tag<gocpp::slice<operand*>>(), n);
            for(auto [i, e] : elist)
            {
                operand x = {};
                rec::expr(gocpp::recv(check), nullptr, & x, e);
                xlist[i] = & x;
            }
        }
        return xlist;
    }

